// The whoishiring account posts three threads a month: "Who is hiring?",
// "Who wants to be hired?" and "Freelancer?". Only the first is a list of
// companies, and search_by_date returns whichever went up most recently, so
// the title has to be matched rather than trusted.
const hits = ($('Fetch HN Index').first().json || {}).hits || [];
const hiring = hits.filter(h => /who is hiring/i.test(h.title || ''));

if (hiring.length === 0) {
  // Not an error worth stopping the workflow for - YC alone is a full run, and
  // the thread reappears on the first of next month.
  return [{ json: { story_id: null, story_title: null, skipped: 'no "Who is hiring?" thread found' } }];
}

// search_by_date is newest first.
const newest = hiring[0];
return [{ json: {
  story_id: newest.objectID,
  story_title: newest.title,
  story_created_at: newest.created_at
} }];

// Turn three public sources into candidate companies.
//
// The filters here encode one thesis, and it is the inverse of the one this
// repository shipped with: the buyer runs production software and has nobody
// whose job is to run it. So a company advertising for a DevOps engineer is
// REJECTED, not scored highly - it has diagnosed the problem itself and has a
// salary approved. See prompts/scoring.md.
//
// Nothing here decides whether a company is worth contacting. That is WF-02's
// and WF-04's work, and both are better at it than a regular expression. This
// node only decides what is worth paying a research model to look at.

const NOW_YEAR       = new Date().getUTCFullYear();
const MIN_TEAM       = Number($env.DISCOVERY_MIN_TEAM_SIZE || 10);
const MAX_TEAM       = Number($env.DISCOVERY_MAX_TEAM_SIZE || 120);
const MAX_BATCH_AGE  = Number($env.DISCOVERY_MAX_BATCH_AGE_YEARS || 8);
const DAILY_LIMIT    = Number($env.DISCOVERY_DAILY_LIMIT || 25);
// The day's slots are shared by ICP segment in Record Candidates
// (icp_segments.discovery_share, 0025), not by source any more.

// A role that means they are hiring the solution instead of buying it.
const INFRA_ROLE = /\b(devops|sre|site\s*reliability|platform\s+engineer|infrastructure\s+engineer|infra\s+engineer|cloud\s+engineer|systems\s+engineer|production\s+engineer|kubernetes\s+engineer)\b/i;
// Any engineering role at all. No engineering role means no infrastructure.
const ENG_ROLE   = /\b(engineer|developer|swe|programmer|architect|cto)\b/i;
// A company selling infrastructure tooling employs infrastructure people, and
// is a competitor besides.
const VENDOR     = /(devops|\bsre\b|observability|kubernetes|ci\/?cd|infrastructure|platform engineering|finops|terraform|deployment|incident response|uptime|apm|log management)/i;
// The same idea for a Hacker News listing, which has no one-line description to
// test. It has to run against the whole post, so it is narrower: only phrases
// that describe a company's own product, never a word that shows up in prose.
// A post that mentions on-call or observability at all is disqualifying either
// way - a company with an on-call rotation has the infrastructure practice this
// system exists to supply.
const VENDOR_PRODUCT = /(observability|uptime monitoring|incident management|incident response|log management|on-?call|\bapm\b|application performance monitoring|infrastructure monitoring|ci\/cd platform|developer platform|kubernetes platform|cloud cost|finops)/i;

// Applicant tracking systems and link shorteners. A posting that only links to
// one of these has not told us the company's domain, and inserting the ATS as
// a company would poison the table.
const NOT_A_COMPANY = new Set([
  'greenhouse.io','lever.co','ashbyhq.com','workable.com','breezy.hr','recruitee.com',
  'bamboohr.com','bamboohr.co.uk','jobvite.com','smartrecruiters.com','myworkdayjobs.com',
  'workday.com','trinethire.com','jazzhr.com','applytojob.com','rippling.com','paylocity.com',
  'gethired.com','teamtailor.com','pinpointhq.com','notion.site','notion.so','docs.google.com',
  'forms.gle','linkedin.com','github.io','github.com','angel.co','wellfound.com','ycombinator.com',
  'bit.ly','tinyurl.com','twitter.com','x.com','youtube.com','medium.com',
  // Shorteners hide the company behind a redirect: Flow Traders went in as
  // lnkd.in on 2026-09-23 and stuck at 'researching'.
  'lnkd.in','t.co','ow.ly','buff.ly','rebrand.ly','bitly.com','cutt.ly','is.gd','shorturl.at','tiny.cc'
]);

// A recruiting subdomain is not a company. careers.snowflake.com went into the
// companies table on the first live run and would have been researched as if it
// were a distinct company from snowflake.com.
const RECRUITING_SUBDOMAIN = /^(careers|jobs|apply|join|boards|hire|hiring|work|recruiting|talent)\./;

function toDomain(url) {
  const m = /^https?:\/\/([^/\s?#]+)/i.exec((url || '').trim());
  if (!m) return null;
  let d = m[1].toLowerCase().split(':')[0];
  if (d.startsWith('www.')) d = d.slice(4);
  if (RECRUITING_SUBDOMAIN.test(d)) d = d.replace(RECRUITING_SUBDOMAIN, '');
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(d)) return null;
  const parts = d.split('.');
  const registrable = parts.slice(-2).join('.');
  if (NOT_A_COMPANY.has(d) || NOT_A_COMPANY.has(registrable)) return null;
  return d;
}

const candidates = [];
const stats = { yc_total: 0, yc_rejected: {}, hn_total: 0, hn_rejected: {}, hn_thread: null,
                osm_total: 0, osm_rejected: {}, osm_countries: {}, osm_failed: [], osm_origin: {} };
const rejectYc = (r) => { stats.yc_rejected[r] = (stats.yc_rejected[r] || 0) + 1; };
const rejectHn = (r) => { stats.hn_rejected[r] = (stats.hn_rejected[r] || 0) + 1; };
const rejectOsm = (r) => { const k = r.replace(/\d+ locations/, 'N locations'); stats.osm_rejected[k] = (stats.osm_rejected[k] || 0) + 1; };

// ---------------------------------------------------------------- Y Combinator
// Fetched as text and parsed here: the response is a top-level JSON array, and
// letting n8n parse it turns 6000 companies into 6000 items for no purpose.
let yc = [];
try {
  yc = JSON.parse($('Fetch YC Directory').first().json.data || '[]');
} catch (e) {
  throw new Error('YC directory did not parse as JSON: ' + e.message);
}
stats.yc_total = yc.length;

for (const c of yc) {
  if (c.status !== 'Active')       { rejectYc('not active'); continue; }
  const ts = c.team_size;
  if (!ts || ts < MIN_TEAM || ts > MAX_TEAM) { rejectYc('team size out of band'); continue; }
  if (c.nonprofit)                 { rejectYc('nonprofit'); continue; }
  const domain = toDomain(c.website);
  if (!domain)                     { rejectYc('no usable domain'); continue; }
  // Tested against the short fields only. A long description says "deploy"
  // about its own product often enough to reject half the directory.
  if (VENDOR.test([c.one_liner || '', (c.tags || []).join(' ')].join(' ')))
                                   { rejectYc('sells infrastructure tooling'); continue; }
  const ym = /(19|20)\d{2}/.exec(c.batch || '');
  const batchYear = ym ? Number(ym[0]) : null;
  if (batchYear === null || batchYear < NOW_YEAR - MAX_BATCH_AGE)
                                   { rejectYc('batch older than the window'); continue; }

  // Priority, highest first. Hiring now dominates, then the size band where a
  // company is certain to have no platform team, then recency.
  const priority = (c.isHiring ? 100 : 0)
                 + (ts >= 15 && ts <= 80 ? 50 : 0)
                 + (batchYear - (NOW_YEAR - MAX_BATCH_AGE));

  candidates.push({
    source: 'radar_yc',
    external_id: c.slug || String(c.id),
    domain,
    name: c.name,
    website: c.website || null,
    country: (c.all_locations || '').split(',').pop().trim() || null,
    industry: c.industry || null,
    employee_count: ts,
    description: (c.one_liner || '').slice(0, 500) || null,
    priority,
    evidence: {
      url: c.url || null,
      note: 'YC ' + (c.batch || 'unknown batch') + ', team size ' + ts
          + (c.isHiring ? ', currently hiring' : '') + '. '
          + 'Team size is the whole company, so the engineering team is smaller; '
          + 'whether anyone owns infrastructure is unverified and is WF-02 work.'
    }
  });
}

// ------------------------------------------------- Hacker News "Who is hiring?"
// The strongest free signal for this thesis. Each top-level comment is one
// company listing its open roles, so the roles it does NOT list are readable.
const thread = $('Fetch HN Thread').first().json || {};
const children = thread.children || [];
stats.hn_total = children.length;
stats.hn_thread = thread.id || null;

for (const c of children) {
  const raw = c.text || '';
  if (!raw) { rejectHn('empty comment'); continue; }
  const text = raw.replace(/<[^>]+>/g, ' ')
                  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
                  .replace(/&quot;/g, '"').replace(/&#x27;/g, "'").replace(/&#x2F;/g, '/');
  const header = text.split('\n')[0].slice(0, 400);

  // The whole point. They are hiring the person being sold.
  if (INFRA_ROLE.test(text))      { rejectHn('hiring infrastructure'); continue; }
  if (VENDOR_PRODUCT.test(text))  { rejectHn('sells or operates infrastructure tooling'); continue; }
  if (!ENG_ROLE.test(header))     { rejectHn('no engineering role in the header'); continue; }

  const urls = raw.replace(/&#x2F;/g, '/').match(/https?:\/\/[^\s<>"')]+/g) || [];
  let domain = null;
  for (const u of urls) { const d = toDomain(u); if (d) { domain = d; break; } }
  if (!domain)                    { rejectHn('no usable domain'); continue; }

  candidates.push({
    source: 'radar_hn',
    external_id: String(c.id),
    domain,
    // Most listings open "Company | Role | Location". The ones that do not are
    // prose, and the first 120 characters of prose is not a company name - the
    // domain is a worse name but never an embarrassing one, and WF-02 corrects
    // it from the company's own site either way.
    name: (header.includes('|')
            ? header.split('|')[0].replace(/\([^)]*https?:[^)]*\)/gi, '').trim().slice(0, 120)
            : '') || domain,
    website: 'https://' + domain,
    country: null,
    industry: null,
    employee_count: null,
    description: header.slice(0, 500),
    // Above every YC candidate on purpose, and this is the one ordering
    // decision in the file that matters. The YC directory is permanent - a
    // company deferred today is still there next week. The HN thread is a
    // one-month window that is replaced on the first of the month, so a
    // listing not taken now is not deferred, it is lost. Perishable first.
    priority: 200,
    evidence: {
      url: 'https://news.ycombinator.com/item?id=' + c.id,
      note: 'Hacker News "Who is hiring?" ' + String(thread.title || '').replace(/^Ask HN: /, '')
          + '. Listed roles with no infrastructure role among them: '
          + header.slice(0, 200)
    }
  });
}

// ------------------------------------------------------------- OpenStreetMap
// Businesses in the region that list a website: the source for the automation
// line (docs/lead-discovery.md). One Overpass response per country, each item
// carrying the ISO code it was asked for.
//
// A chain is not a prospect: the same domain on more than a few map points is
// a retailer with a head office, a procurement department and an IT team. The
// categories are an allowlist of businesses whose work is orders, stock,
// shipments or clients - the repetitive back office this line sells against.
const OSM_MAX_LOCATIONS = Number($env.DISCOVERY_OSM_MAX_LOCATIONS || 3);
// The weights follow the active ICP segments (0024_icp_segments.sql): the
// categories a segment has an offer for are read first, the rest (the
// regional_other control) after them.
const OSM_OFFICE = {
  logistics: 40, courier: 40, advertising_agency: 40, marketing: 40, accountant: 40,
  employment_agency: 15, travel_agent: 15, insurance: 10, estate_agent: 10,
  consulting: 10, company: 5, it: 5,
};
const OSM_SHOP = new Set([
  'furniture','electronics','computer','mobile_phone','appliance','clothes','shoes','bag',
  'fashion_accessories','jewelry','watches','cosmetics','perfumery','sports','outdoor',
  'bicycle','car_parts','tyres','hardware','doityourself','houseware','kitchen','lighting',
  'interior_decoration','bathroom_furnishing','tiles','flooring','paint','garden_centre',
  'pet','toys','baby_goods','books','stationery','gift','wine','alcohol','coffee','tea',
  'health_food','medical_supply','fabric','sewing','wholesale','trade','agrarian',
]);
// Places that are not the company: social profiles, site builders' free
// subdomains, marketplaces and link pages.
const OSM_NOT_A_SITE = /(^|\.)(facebook\.com|instagram\.com|google\.com|goo\.gl|business\.site|wixsite\.com|linktr\.ee|tiktok\.com|olx\.ba|kupujemprodajem\.com|njuskalo\.hr|booking\.com|tripadvisor\.com|wa\.me|viber\.com|blogspot\.com|wordpress\.com)$/;

// OSM Snapshot answers one item per country: the last good response WF-12
// saved (origin 'snapshot'), or nothing yet (origin 'none').
const osmSeen = new Map();
for (const item of $('OSM Snapshot').all()) {
  const iso = item.json.iso;
  if (!iso) continue;
  stats.osm_origin[iso] = item.json.origin + (item.json.problem ? ' (' + item.json.problem + ')' : '');
  let els = [];
  try { els = JSON.parse(item.json.data || '').elements || []; }
  catch (e) { stats.osm_failed.push(iso); continue; }
  stats.osm_countries[iso] = els.length;
  for (const e of els) {
    const t = e.tags || {};
    const site = t.website || t['contact:website'];
    const domain = toDomain(/^https?:\/\//i.test(site || '') ? site : 'https://' + (site || ''));
    if (!domain || OSM_NOT_A_SITE.test(domain)) { rejectOsm('no company website'); continue; }
    const entry = osmSeen.get(domain) || { domain, count: 0, first: e, iso, kind: null, weight: -1, brand: null };
    entry.count += 1;
    // brand:wikidata / operator:wikidata is how OSM marks a branch of a known
    // chain (the Name Suggestion Index). A country has one DHL depot, so the
    // location count alone let DHL, DB Schenker and Adecco through to research
    // on 2026-09-25. About one element in five carries the tag.
    entry.brand = entry.brand || t['brand:wikidata'] || t['operator:wikidata'] || null;
    const weight = t.office ? (OSM_OFFICE[t.office] ?? -1) : (OSM_SHOP.has(t.shop) ? 35 : -1);
    if (weight > entry.weight) { entry.weight = weight; entry.first = e; entry.kind = t.office ? 'office=' + t.office : 'shop=' + t.shop; }
    osmSeen.set(domain, entry);
  }
}
stats.osm_total = osmSeen.size;
for (const o of osmSeen.values()) {
  if (o.count > OSM_MAX_LOCATIONS) { rejectOsm('chain: ' + o.count + ' locations'); continue; }
  if (o.brand)                     { rejectOsm('branch of a known chain'); continue; }
  if (o.weight < 0)                { rejectOsm('category outside the allowlist'); continue; }
  const t = o.first.tags || {};
  const city = t['addr:city'] || t['addr:place'] || null;
  candidates.push({
    source: 'radar_osm',
    external_id: o.first.type + '/' + o.first.id,
    domain: o.domain,
    name: (t.name || t.brand || o.domain).slice(0, 120),
    website: 'https://' + o.domain,
    country: o.iso,
    industry: 'OSM ' + o.kind,
    employee_count: null,
    description: [o.kind, city].filter(Boolean).join(', ').slice(0, 500),
    // Ranks candidates inside their ICP segment; how many a segment gets is
    // its discovery_share (0025_segment_allocation.sql), not the priority.
    priority: 150 + o.weight,
    evidence: {
      url: 'https://www.openstreetmap.org/' + o.first.type + '/' + o.first.id,
      note: 'OpenStreetMap: ' + o.kind + (city ? ' in ' + city : '') + ', ' + o.iso
          + ', website listed, ' + o.count + ' location(s). Map data (c) OpenStreetMap contributors, ODbL.'
    }
  });
}

// ------------------------------------------------- Minimax's office directory
// The accounting offices that use Minimax, as Minimax lists them so that
// entrepreneurs can find a bookkeeper (0029_minimax_directory.sql). Being on
// the list is itself the sourced fact a segment email opens with - the office
// keeps its clients' books in Minimax - so the signal carries a confidence the
// map's categories never earn.
stats.directory_total = 0; stats.directory_countries = {};
for (const item of $('Directory Snapshot').all()) {
  const j = item.json;
  if (!j.iso || j.source !== 'radar_minimax') continue;
  let entries = [];
  try { entries = JSON.parse(j.data || '[]'); } catch (e) { stats.osm_failed.push('minimax ' + j.iso); continue; }
  stats.directory_countries[j.iso] = entries.length;
  for (const o of entries) {
    const domain = toDomain('https://' + (o.domain || ''));
    if (!domain || OSM_NOT_A_SITE.test(domain)) continue;
    stats.directory_total += 1;
    candidates.push({
      source: 'radar_minimax',
      external_id: j.iso + '/' + o.slug,
      domain,
      name: String(o.name || domain).slice(0, 120),
      website: o.website ? (/^https?:\/\//i.test(o.website) ? o.website.trim() : 'https://' + o.website.trim()) : 'https://' + domain,
      country: j.iso,
      industry: 'Minimax accounting directory',
      employee_count: null,
      description: ['accounting office, works in Minimax', o.city].filter(Boolean).join(', ').slice(0, 500),
      // The same weight as a mapped accountant, a little more when the office
      // gave Minimax a website: research has a page to read.
      priority: 190 + (o.website ? 5 : 0),
      evidence: {
        url: j.url,
        confidence: 0.9,
        note: 'Listed in Minimax\'s public directory of accounting services (' + j.iso + ')'
            + (o.address ? ', ' + o.address : '') + ', so the office keeps its clients\' books in Minimax.'
      }
    });
  }
}

return [{
  json: {
    daily_limit: DAILY_LIMIT,
    candidate_count: candidates.length,
    candidates,
    stats
  }
}];
